"use client";

import { memo, useCallback, useMemo, useState } from "react";
import type { MediaCarouselHandle, MediaCarouselProps } from "./types";
import { useMediaRecovery } from "./hooks/use-media-recovery";
import {
  DEFAULT_MAX_RATIO,
  DEFAULT_MIN_RATIO,
  clampRatio,
  declaredRatio,
  frameFor,
} from "./lib/aspect";
import { resolveLabels, resolveLocale } from "./lib/labels";
import { CarouselTrack } from "./parts/carousel-track";
import { SingleItem } from "./parts/single-item";

interface MediaCarouselInnerProps extends MediaCarouselProps {
  ref?: React.Ref<MediaCarouselHandle>;
}

function MediaCarouselInner({
  items,
  variant,
  peekRatio = 0.075,
  aspect = "square",
  minRatio = DEFAULT_MIN_RATIO,
  maxRatio = DEFAULT_MAX_RATIO,
  loop,
  showIndicators = true,
  showNavButtons = true,
  showCounter = false,
  dir: dirProp,
  rtl,
  locale: localeProp,
  index,
  onIndexChange,
  defaultIndex,
  renderItem,
  onSlideChange,
  onDoubleTap,
  onMediaError,
  labels: labelsProp,
  className,
  slideClassName,
  ref,
}: MediaCarouselInnerProps) {
  const labels = useMemo(() => resolveLabels(labelsProp), [labelsProp]);
  const locale = useMemo(() => resolveLocale(localeProp), [localeProp]);
  const formatter = useMemo(() => new Intl.NumberFormat(locale), [locale]);
  const formatNumber = useCallback((n: number) => formatter.format(n), [formatter]);
  const recovery = useMediaRecovery(onMediaError);

  // `natural-clamped`: the first item's declared size, else its loaded natural size
  // (square until it loads). Keyed by id so a new first item starts over.
  const first = items[0];
  const [natural, setNatural] = useState<{ id: string; ratio: number } | null>(null);
  const declared = declaredRatio(first, minRatio, maxRatio);
  const needsNatural = aspect === "natural-clamped" && declared === null && !!first;
  const naturalRatio =
    natural && first && natural.id === first.id ? clampRatio(natural.ratio, 1, minRatio, maxRatio) : null;
  const firstId = first?.id;
  const onNaturalSize = useCallback(
    (width: number, height: number) => {
      if (!firstId || !width || !height) return;
      setNatural((prev) =>
        prev && prev.id === firstId && prev.ratio === width / height ? prev : { id: firstId, ratio: width / height },
      );
    },
    [firstId],
  );
  const frame = useMemo(
    () => frameFor(aspect, declared ?? naturalRatio),
    [aspect, declared, naturalRatio],
  );

  // `dir` wins; the deprecated `rtl` only when set; otherwise resolved from the element.
  const dir = dirProp ?? (rtl === undefined ? undefined : rtl ? "rtl" : "ltr");

  if (items.length === 0) return null;

  if (items.length === 1) {
    return (
      <SingleItem
        item={items[0]}
        renderItem={renderItem}
        onDoubleTap={onDoubleTap}
        labels={labels}
        frame={frame}
        recovery={recovery}
        onNaturalSize={needsNatural ? onNaturalSize : undefined}
        dir={dir}
        className={className}
        slideClassName={slideClassName}
      />
    );
  }

  return (
    <CarouselTrack
      ref={ref}
      items={items}
      variant={variant}
      peekRatio={peekRatio}
      frame={frame}
      loop={loop ?? true}
      showIndicators={showIndicators}
      showNavButtons={showNavButtons}
      showCounter={showCounter}
      dir={dir}
      formatNumber={formatNumber}
      index={index}
      defaultIndex={defaultIndex}
      onIndexChange={onIndexChange}
      renderItem={renderItem}
      onSlideChange={onSlideChange}
      onDoubleTap={onDoubleTap}
      recovery={recovery}
      onNaturalSize={needsNatural ? onNaturalSize : undefined}
      labels={labels}
      className={className}
      slideClassName={slideClassName}
    />
  );
}

const MediaCarousel = memo(MediaCarouselInner);
MediaCarousel.displayName = "MediaCarousel";

export { MediaCarousel };
export default MediaCarousel;

export { default as MediaCarousel } from "./media-carousel";

export type {
  MediaCarouselProps,
  MediaCarouselHandle,
  MediaCarouselLabels,
  ResolvedMediaCarouselLabels,
  MediaCarouselVariant,
  MediaCarouselAspect,
  MediaCarouselDirection,
  MediaItem,
  RenderItemContext,
  LinearAspect,
} from "./types";

export { defaultMediaCarouselLabels, DEFAULT_MEDIA_CAROUSEL_LABELS } from "./types";

// @ilinxa/media-carousel 0.3.0

import type { ReactNode } from "react";

export type MediaCarouselVariant = "gallery" | "linear";

/** The fixed aspect ratios (the 0.2 set). */
export type LinearAspect = "square" | "video" | "portrait" | "auto";

/**
 * Slide frame ratio. `natural-clamped` = the first item's own ratio, clamped to
 * `[minRatio, maxRatio]` (width / height) — e.g. 3:4 → 4:5, 16:9 stays, 3:1 → 1.91:1.
 */
export type MediaCarouselAspect = LinearAspect | "natural-clamped";

export type MediaCarouselDirection = "ltr" | "rtl";

/** Discriminated union — strict shape. */
export type MediaItem =
  | {
      id: string;
      type: "image";
      url: string;
      alt?: string;
      /** Intrinsic size in px — reserves the frame before load and feeds `natural-clamped`. */
      width?: number;
      height?: number;
      /** Forwarded to the built-in `<img>`. */
      srcSet?: string;
      sizes?: string;
    }
  | {
      id: string;
      type: "video";
      url: string;
      alt?: string;
      poster?: string;
      /** Intrinsic size in px — feeds `natural-clamped` before the metadata loads. */
      width?: number;
      height?: number;
    };

export interface RenderItemContext {
  /** True when this slide is the currently centered/snapped slide. */
  isActive: boolean;
  /**
   * True while at least half of the carousel is in the viewport (always true on the server
   * and the first render). The built-in video plays only when `isActive && inView` — a custom
   * video renderer should use the same condition.
   */
  inView: boolean;
  /** Index of this slide in the items array. */
  index: number;
}

export interface MediaCarouselLabels {
  /** Default: "Media carousel". aria-label on the carousel region. */
  carouselLabel?: string;
  /** Default: "Previous slide". aria-label on the prev nav button. */
  previousSlide?: string;
  /** Default: "Next slide". aria-label on the next nav button. */
  nextSlide?: string;
  /**
   * Indicator dot name: `(position) => string`, position 1-based. Default `"Go to slide 2"`.
   * A string is the deprecated 0.2 form: a prefix, named `"{prefix} {n}"`.
   */
  goToSlide?: string | ((position: number) => string);
  /**
   * Slide name: `(position, total) => string`, position 1-based. Default `"Slide 2 of 5"`.
   * A string is the deprecated 0.2 template with `{index}` / `{total}` placeholders.
   */
  slideAriaLabel?: string | ((position: number, total: number) => string);
  /**
   * Visible counter chip (`showCounter`). `format` renders a number in `locale`.
   * Default `"2/5"`.
   */
  counter?: (position: number, total: number, format: (n: number) => string) => string;
  /** Default: "carousel". `aria-roledescription` of the region. */
  carouselRoleDescription?: string;
  /** Default: "slide". `aria-roledescription` of each slide. */
  slideRoleDescription?: string;
}

/** Labels after merging over the defaults — every value present, value labels as functions. */
export interface ResolvedMediaCarouselLabels {
  carouselLabel: string;
  previousSlide: string;
  nextSlide: string;
  goToSlide: (position: number) => string;
  slideAriaLabel: (position: number, total: number) => string;
  counter: (position: number, total: number, format: (n: number) => string) => string;
  carouselRoleDescription: string;
  slideRoleDescription: string;
}

export interface MediaCarouselProps {
  /** Items to render. Required. */
  items: MediaItem[];
  /** Variant — `gallery` (peek-scale) or `linear` (snap). Required. */
  variant: MediaCarouselVariant;

  // ─── Per-variant config ──────────────────────────────────────────
  /** Gallery only: peek ratio per side (e.g., 0.075 = 7.5%). Default: 0.075. */
  peekRatio?: number;
  /**
   * Slide frame ratio, for both variants and a single item. Default: "square".
   * In a gallery every slide uses the same frame (the first item's, for `natural-clamped`).
   */
  aspect?: MediaCarouselAspect;
  /** `natural-clamped` lower bound (width / height). Default: 4 / 5. */
  minRatio?: number;
  /** `natural-clamped` upper bound (width / height). Default: 1.91. */
  maxRatio?: number;

  // ─── Carousel behavior ───────────────────────────────────────────
  /** Loop slides. Default: items.length > 1. */
  loop?: boolean;
  /** Show indicator dots. Default: true. Always hidden when items.length <= 1. */
  showIndicators?: boolean;
  /**
   * Side nav buttons. Default: true. `"fine-pointer"` = only under a mouse / trackpad
   * (`(pointer: fine)`, resolved after mount). Always hidden when items.length <= 1.
   */
  showNavButtons?: boolean | "fine-pointer";
  /** Visible "2/5" chip. Default: false. */
  showCounter?: boolean;
  /**
   * Text direction. Default: the element's direction after mount (an ancestor `dir="rtl"`
   * works). Embla, arrow keys, chevrons, nav sides, peek and fades all follow it.
   */
  dir?: MediaCarouselDirection;
  /** @deprecated Use `dir="rtl"`. Ignored when `dir` is set. */
  rtl?: boolean;
  /** BCP 47 locale for the counter numbers. Default: "en"; an invalid tag falls back to "en". */
  locale?: string;

  // ─── Controlled index (opt-in) ───────────────────────────────────
  /**
   * Controlled slide index. When set, the prop wins on every render: a swipe calls
   * `onIndexChange` and settles back unless the parent adopts the new index.
   */
  index?: number;
  /** Fires when the user (or the handle) moves to another slide. */
  onIndexChange?: (index: number) => void;
  /** Starting slide when uncontrolled. Default: 0. */
  defaultIndex?: number;

  // ─── Customization ───────────────────────────────────────────────
  /** Custom per-slide renderer — bypasses both built-in handlers. */
  renderItem?: (item: MediaItem, ctx: RenderItemContext) => ReactNode;

  // ─── Callbacks ───────────────────────────────────────────────────
  /** Fires on Embla `select` event (post-snap; once per slide commit). */
  onSlideChange?: (index: number) => void;
  /** Fires on double-tap of any slide. Unified for image + video items. */
  onDoubleTap?: (item: MediaItem, index: number) => void;
  /**
   * A built-in image or video failed to load (an expired signed URL…). Resolve a new URL to
   * retry once; a second failure for the same item does not call again. A new `url` from the
   * host resets it. A retried video starts from 0.
   */
  onMediaError?: (item: MediaItem) => Promise<string | void> | string | void;

  // ─── i18n ────────────────────────────────────────────────────────
  /** Localized labels. Defaults are English; an `undefined` value keeps the default. */
  labels?: MediaCarouselLabels;

  // ─── Style overrides ─────────────────────────────────────────────
  /**
   * Override classes for the wrapping <div>. CSS variables: `--media-carousel-fade` (edge
   * fade colour, default `var(--background)`), `--media-carousel-inactive-blur` (default `1px`).
   */
  className?: string;
  /** Override classes per slide wrapper. */
  slideClassName?: string;
}

export interface MediaCarouselHandle {
  /** Scroll to a specific slide (0-indexed). */
  scrollTo: (index: number) => void;
  /** Scroll to previous slide. */
  scrollPrev: () => void;
  /** Scroll to next slide. */
  scrollNext: () => void;
  /** Get the currently active slide index. */
  getCurrentIndex: () => number;
}

/** Default English labels — exported for consumer composition. */
export const defaultMediaCarouselLabels: ResolvedMediaCarouselLabels = {
  carouselLabel: "Media carousel",
  previousSlide: "Previous slide",
  nextSlide: "Next slide",
  goToSlide: (position) => `Go to slide ${position}`,
  slideAriaLabel: (position, total) => `Slide ${position} of ${total}`,
  counter: (position, total, format) => `${format(position)}/${format(total)}`,
  carouselRoleDescription: "carousel",
  slideRoleDescription: "slide",
};

/**
 * @deprecated The 0.2 string labels — use `defaultMediaCarouselLabels`. Still accepted as
 * `labels`.
 */
export const DEFAULT_MEDIA_CAROUSEL_LABELS = {
  carouselLabel: "Media carousel",
  previousSlide: "Previous slide",
  nextSlide: "Next slide",
  goToSlide: "Go to slide",
  slideAriaLabel: "Slide {index} of {total}",
} as const satisfies MediaCarouselLabels;

"use client";

import type { ReactNode } from "react";
import { useRef } from "react";
import { cn } from "@/lib/utils";
// F-S1 lock: same-category cross-procomp via relative + specific-file path.
import { useDoubleTap } from "../../video-player/hooks/use-double-tap";
import { useInView } from "../hooks/use-environment";
import type { MediaRecovery } from "../hooks/use-media-recovery";
import type { FrameStyle } from "../lib/aspect";
import { SlideRenderer } from "./slide-renderer";
import type {
  MediaItem,
  RenderItemContext,
  ResolvedMediaCarouselLabels,
} from "../types";

interface SingleItemProps {
  item: MediaItem;
  renderItem?: (item: MediaItem, ctx: RenderItemContext) => ReactNode;
  onDoubleTap?: (item: MediaItem, index: number) => void;
  labels: ResolvedMediaCarouselLabels;
  frame: FrameStyle;
  recovery: MediaRecovery;
  onNaturalSize?: (width: number, height: number) => void;
  /** Explicit direction; written on the root so a `renderItem` follows it. */
  dir?: "ltr" | "rtl";
  className?: string;
  slideClassName?: string;
}

/**
 * Single-item shortcut — bypass Embla entirely.
 *
 * Lives in its own component so `useDoubleTap` is called unconditionally
 * within it (own hook count, distinct from `<CarouselTrack>`). Switching
 * between single-item and carousel modes happens via component swap at
 * the root, not conditional hook calls.
 */
export function SingleItem({
  item,
  renderItem,
  onDoubleTap,
  labels,
  frame,
  recovery,
  onNaturalSize,
  dir,
  className,
  slideClassName,
}: SingleItemProps) {
  const rootRef = useRef<HTMLDivElement>(null);
  const inView = useInView(rootRef);
  const handleDoubleTap = useDoubleTap(
    onDoubleTap ? () => onDoubleTap(item, 0) : undefined,
  );

  return (
    <div
      ref={rootRef}
      role="group"
      dir={dir}
      className={cn("relative overflow-hidden bg-muted", className)}
      onClick={handleDoubleTap}
      aria-label={labels.carouselLabel}
    >
      <SlideRenderer
        item={item}
        ctx={{ isActive: true, inView, index: 0 }}
        renderItem={renderItem}
        // Already handled at wrapper level; don't double-fire.
        onDoubleTap={undefined}
        frame={frame}
        recovery={recovery}
        onNaturalSize={onNaturalSize}
        slideClassName={slideClassName}
      />
    </div>
  );
}

"use client";

import type { KeyboardEvent as ReactKeyboardEvent, ReactNode, Ref } from "react";
import {
  useCallback,
  useEffect,
  useImperativeHandle,
  useMemo,
  useRef,
  useState,
} from "react";
import { cn } from "@/lib/utils";
// F-S1 lock: same-category cross-procomp via relative + specific-file path.
import { useDoubleTap } from "../../video-player/hooks/use-double-tap";
import { useDirection } from "../hooks/use-direction";
import { useEmblaWithState } from "../hooks/use-embla-with-state";
import { useFinePointer, useInView } from "../hooks/use-environment";
import type { MediaRecovery } from "../hooks/use-media-recovery";
import type { FrameStyle } from "../lib/aspect";
import type {
  MediaCarouselDirection,
  MediaCarouselHandle,
  MediaCarouselVariant,
  MediaItem,
  RenderItemContext,
  ResolvedMediaCarouselLabels,
} from "../types";
import { IndicatorDots } from "./indicator-dots";
import { NavButtons } from "./nav-buttons";
import { SlideRenderer } from "./slide-renderer";

interface CarouselTrackProps {
  items: MediaItem[];
  variant: MediaCarouselVariant;
  peekRatio: number;
  frame: FrameStyle;
  loop: boolean;
  showIndicators: boolean;
  showNavButtons: boolean | "fine-pointer";
  showCounter: boolean;
  /** Explicit direction (`dir`, or the deprecated `rtl`); otherwise resolved after mount. */
  dir?: MediaCarouselDirection;
  formatNumber: (n: number) => string;
  index?: number;
  defaultIndex?: number;
  onIndexChange?: (index: number) => void;
  renderItem?: (item: MediaItem, ctx: RenderItemContext) => ReactNode;
  onSlideChange?: (index: number) => void;
  onDoubleTap?: (item: MediaItem, index: number) => void;
  recovery: MediaRecovery;
  onNaturalSize?: (width: number, height: number) => void;
  labels: ResolvedMediaCarouselLabels;
  className?: string;
  slideClassName?: string;
  ref?: Ref<MediaCarouselHandle>;
}

interface SlideProps {
  item: MediaItem;
  index: number;
  total: number;
  isActive: boolean;
  inView: boolean;
  isFirst: boolean;
  isLast: boolean;
  loop: boolean;
  variant: MediaCarouselVariant;
  peekRatio: number;
  frame: FrameStyle;
  renderItem?: (item: MediaItem, ctx: RenderItemContext) => ReactNode;
  onDoubleTap?: (item: MediaItem, index: number) => void;
  /** Click on a peeking (inactive) neighbour. */
  onSelectNeighbour: (index: number) => void;
  recovery: MediaRecovery;
  onNaturalSize?: (width: number, height: number) => void;
  labels: ResolvedMediaCarouselLabels;
  slideClassName?: string;
}

const clampIndex = (i: number, total: number) =>
  Math.min(Math.max(0, Math.trunc(Number.isFinite(i) ? i : 0)), Math.max(0, total - 1));

function Slide({
  item,
  index,
  total,
  isActive,
  inView,
  isFirst,
  isLast,
  loop,
  variant,
  peekRatio,
  frame,
  renderItem,
  onDoubleTap,
  onSelectNeighbour,
  recovery,
  onNaturalSize,
  labels,
  slideClassName,
}: SlideProps) {
  // Image items: attach double-tap on the slide wrapper. Video items: handled
  // inside SlideRenderer via VideoPlayer's onDoubleTap. Both fire the same
  // unified onDoubleTap callback.
  const imageDoubleTap = useDoubleTap(
    item.type === "image" && onDoubleTap
      ? () => onDoubleTap(item, index)
      : undefined,
  );

  // An inactive slide's content is `inert` (out of the tab order and the accessibility tree,
  // and not a pointer target), so a click on it lands on this wrapper — which scrolls to it.
  // `aria-hidden` keeps the wrapper itself out of the tree too.
  const handleClick = isActive
    ? item.type === "image"
      ? imageDoubleTap
      : undefined
    : () => onSelectNeighbour(index);

  const content = (
    <SlideRenderer
      item={item}
      ctx={{ isActive, inView, index }}
      renderItem={renderItem}
      onDoubleTap={onDoubleTap}
      frame={frame}
      recovery={recovery}
      onNaturalSize={onNaturalSize}
      slideClassName={slideClassName}
    />
  );

  const a11y = {
    role: "group",
    "aria-roledescription": labels.slideRoleDescription,
    "aria-label": labels.slideAriaLabel(index + 1, total),
    "aria-hidden": isActive ? undefined : true,
  } as const;

  if (variant === "gallery") {
    // Edge peek padding only matters when NOT looping. Under loop, Embla
    // positions slides so first/last in view != first/last in source —
    // applying edge padding to the source first/last would create asymmetric
    // slide widths that break Embla's loop math.
    const edgePeekPercent = peekRatio * 100;
    return (
      <div
        {...a11y}
        className={cn("min-w-0 mx-1 flex-[0_0_85%]", !isActive && "cursor-pointer")}
        style={{
          marginInlineStart: !loop && isFirst ? `${edgePeekPercent}%` : undefined,
          marginInlineEnd: !loop && isLast ? `${edgePeekPercent}%` : undefined,
        }}
        onClick={handleClick}
      >
        <div
          inert={!isActive}
          className={cn(
            "overflow-hidden rounded-lg motion-safe:transition-all motion-safe:duration-300",
            isActive
              ? "scale-100 opacity-100"
              : "scale-95 opacity-60 blur-(--media-carousel-inactive-blur,1px)",
          )}
        >
          {content}
        </div>
      </div>
    );
  }

  // Linear: full-width slide, no peek, no scale.
  return (
    <div {...a11y} className="min-w-0 flex-[0_0_100%]" onClick={handleClick}>
      <div inert={!isActive}>{content}</div>
    </div>
  );
}

export function CarouselTrack({
  items,
  variant,
  peekRatio,
  frame,
  loop,
  showIndicators,
  showNavButtons,
  showCounter,
  dir: dirProp,
  formatNumber,
  index: indexProp,
  defaultIndex,
  onIndexChange,
  renderItem,
  onSlideChange,
  onDoubleTap,
  recovery,
  onNaturalSize,
  labels,
  className,
  slideClassName,
  ref: forwardedRef,
}: CarouselTrackProps) {
  const rootRef = useRef<HTMLDivElement>(null);
  const dir = useDirection(rootRef, dirProp);
  const inView = useInView(rootRef);
  const finePointer = useFinePointer();
  const total = items.length;

  const controlled = indexProp !== undefined;
  const target = controlled ? clampIndex(indexProp, total) : undefined;
  // Embla's start slide — read once; later moves go through scrollTo.
  const [startIndex] = useState(() => clampIndex(indexProp ?? defaultIndex ?? 0, total));

  // Memoize Embla options — useEmblaCarousel re-initializes on options identity change.
  // Under loop, Embla force-disables containScroll; we don't set it explicitly there.
  // Under linear+no-loop, we trim duplicate edge snaps so prev/next stop cleanly.
  const emblaOptions = useMemo(
    () => ({
      align: variant === "gallery" ? ("center" as const) : ("start" as const),
      ...(variant === "linear" && !loop
        ? { containScroll: "trimSnaps" as const }
        : {}),
      loop,
      direction: dir,
      startIndex,
    }),
    [variant, loop, dir, startIndex],
  );

  // The controlled index, read by the select handler without re-subscribing.
  const targetRef = useRef(target);
  useEffect(() => {
    targetRef.current = target;
  });

  const handleSelect = useCallback(
    (i: number) => {
      onSlideChange?.(i);
      // Controlled: only a move away from the prop is a request (the settle-back and a
      // prop-driven scroll land on the prop and stay silent).
      if (targetRef.current === undefined || i !== targetRef.current) onIndexChange?.(i);
    },
    [onSlideChange, onIndexChange],
  );

  const { ref, api, currentIndex, scrollTo, scrollPrev, scrollNext } =
    useEmblaWithState({ ...emblaOptions, onSelect: handleSelect });

  // Controlled: the prop wins. Scroll to it when it changes, and settle back to it after a
  // swipe the parent did not adopt (on `settle`, so a drag in progress is never yanked), and
  // after a re-init.
  useEffect(() => {
    if (!controlled || !api) return;
    const correct = () => {
      const t = targetRef.current;
      if (t !== undefined && api.selectedScrollSnap() !== t) api.scrollTo(t);
    };
    correct();
    api.on("settle", correct);
    api.on("reInit", correct);
    return () => {
      api.off("settle", correct);
      api.off("reInit", correct);
    };
  }, [controlled, api, target]);

  const shownIndex = target ?? currentIndex;

  // Stable ref-mirror for the shown index — keeps imperative handle identity
  // stable across slide changes. Ref write inside passive useEffect.
  const currentIndexRef = useRef(shownIndex);
  useEffect(() => {
    currentIndexRef.current = shownIndex;
  });

  useImperativeHandle(
    forwardedRef,
    () => ({
      scrollTo,
      scrollPrev,
      scrollNext,
      getCurrentIndex: () => currentIndexRef.current,
    }),
    [scrollTo, scrollPrev, scrollNext],
  );

  // A click that ends a drag never reaches a slide: Embla stops it in the capture phase on the
  // slide container.
  const selectNeighbour = scrollTo;

  // Gallery variant gets soft edge fades (mirrors kasder UX). Linear variant doesn't
  // — full-width slides have no peek to soften.
  const showEdgeGradients = variant === "gallery";
  const navButtonsVisible =
    showNavButtons === "fine-pointer" ? finePointer : showNavButtons;

  // Keyboard nav — APG carousel pattern: ArrowLeft/Right scroll prev/next
  // (direction-aware), Home/End jump to first/last. Wired on the focusable region
  // wrapper so users tabbing into the carousel get arrow-key control without
  // first focusing a child slide.
  const handleKeyDown = useCallback(
    (e: ReactKeyboardEvent<HTMLDivElement>) => {
      const rtl = dir === "rtl";
      if (e.key === "ArrowLeft") {
        e.preventDefault();
        if (rtl) scrollNext();
        else scrollPrev();
      } else if (e.key === "ArrowRight") {
        e.preventDefault();
        if (rtl) scrollPrev();
        else scrollNext();
      } else if (e.key === "Home") {
        e.preventDefault();
        scrollTo(0);
      } else if (e.key === "End") {
        e.preventDefault();
        scrollTo(total - 1);
      }
    },
    [dir, scrollPrev, scrollNext, scrollTo, total],
  );

  return (
    <div
      ref={rootRef}
      role="region"
      aria-roledescription={labels.carouselRoleDescription}
      aria-label={labels.carouselLabel}
      // Only an explicit direction is written, so an inherited one is never overridden.
      dir={dirProp}
      data-dir={dirProp}
      tabIndex={0}
      onKeyDown={handleKeyDown}
      className={cn(
        "group/media-carousel relative outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 rounded-md",
        className,
      )}
    >
      <div className="overflow-hidden" ref={ref}>
        <div className="flex">
          {items.map((item, index) => (
            <Slide
              key={item.id}
              item={item}
              index={index}
              total={total}
              isActive={index === shownIndex}
              inView={inView}
              isFirst={index === 0}
              isLast={index === total - 1}
              loop={loop}
              variant={variant}
              peekRatio={peekRatio}
              frame={frame}
              renderItem={renderItem}
              onDoubleTap={onDoubleTap}
              onSelectNeighbour={selectNeighbour}
              recovery={recovery}
              onNaturalSize={index === 0 ? onNaturalSize : undefined}
              labels={labels}
              slideClassName={slideClassName}
            />
          ))}
        </div>
      </div>

      {showEdgeGradients ? (
        <>
          <div
            aria-hidden="true"
            className="pointer-events-none absolute inset-y-0 start-0 z-5 w-12 bg-linear-to-r rtl:bg-linear-to-l group-data-[dir=ltr]/media-carousel:bg-linear-to-r from-(--media-carousel-fade,var(--background)) to-transparent"
          />
          <div
            aria-hidden="true"
            className="pointer-events-none absolute inset-y-0 end-0 z-5 w-12 bg-linear-to-l rtl:bg-linear-to-r group-data-[dir=ltr]/media-carousel:bg-linear-to-l from-(--media-carousel-fade,var(--background)) to-transparent"
          />
        </>
      ) : null}

      {showCounter ? (
        <div
          aria-hidden="true"
          className={cn(
            "pointer-events-none absolute top-3 z-10 rounded-full bg-background/80 px-2 py-0.5 text-xs font-medium tabular-nums text-foreground",
            // Gallery: inside the centred slide (85 % wide), not over the peeking neighbour.
            variant === "gallery" ? "end-[calc(7.5%_+_0.75rem)]" : "end-3",
          )}
        >
          {labels.counter(shownIndex + 1, total, formatNumber)}
        </div>
      ) : null}

      {navButtonsVisible && (
        <NavButtons
          scrollPrev={scrollPrev}
          scrollNext={scrollNext}
          labels={labels}
        />
      )}

      {showIndicators && (
        <IndicatorDots
          total={total}
          currentIndex={shownIndex}
          scrollTo={scrollTo}
          labels={labels}
        />
      )}
    </div>
  );
}

