import { useEffect, useLayoutEffect, useState } from "react";

const useIsoLayoutEffect = typeof window === "undefined" ? useEffect : useLayoutEffect;

export type Direction = "ltr" | "rtl";

/**
 * Resolves text direction (consumer contract C4 / R6): the `dir` prop wins; otherwise the
 * element's direction, read after mount — the computed `direction`, or the nearest explicit
 * non-`auto` `[dir]` ancestor (jsdom has no UA stylesheet for `dir`); otherwise `"ltr"`.
 *
 * The server render and the first client render both return the prop or `"ltr"`, so markup
 * must not depend on the resolved value before mount. Key handling, swipe, carousel and
 * transition logic may. A later direction change is not observed — pass `dir` if the app
 * switches direction at runtime without remounting.
 *
 * Directional props take `"start" | "end"`; physical values stay only as deprecated aliases.
 * Copy into a component's `hooks/`. Canonical copy: `_template/_snippets/` (tests next to it).
 */
export function useDirection(
  ref: React.RefObject<HTMLElement | null>,
  dirProp?: Direction,
): Direction {
  const [resolved, setResolved] = useState<Direction>("ltr");
  useIsoLayoutEffect(() => {
    if (dirProp) return;
    const el = ref.current;
    if (!el) return;
    const explicit = el.closest('[dir]:not([dir="auto"])')?.getAttribute("dir")?.toLowerCase();
    const rtl = getComputedStyle(el).direction === "rtl" || explicit === "rtl";
    setResolved(rtl ? "rtl" : "ltr");
  }, [dirProp, ref]);
  return dirProp ?? resolved;
}

"use client";

import { useEffect, useState, useSyncExternalStore } from "react";

const FINE_POINTER = "(pointer: fine)";

function subscribeFinePointer(onChange: () => void) {
  if (typeof window === "undefined" || !window.matchMedia) return () => {};
  const mq = window.matchMedia(FINE_POINTER);
  mq.addEventListener("change", onChange);
  return () => mq.removeEventListener("change", onChange);
}

const readFinePointer = () =>
  typeof window !== "undefined" && !!window.matchMedia && window.matchMedia(FINE_POINTER).matches;
const serverFalse = () => false;
const STEPS = Array.from({ length: 21 }, (_, i) => i / 20);

/**
 * True under a fine pointer (mouse / trackpad). The server snapshot is `false`, so the server
 * render and the hydrating client render agree; the real value lands right after hydration.
 */
export function useFinePointer(): boolean {
  return useSyncExternalStore(subscribeFinePointer, readFinePointer, serverFalse);
}

/**
 * True while at least `threshold` of the element is in the viewport — or, for an element
 * taller than the viewport, while it covers at least `threshold` of the viewport. Starts `true`
 * (server, first render, and environments without IntersectionObserver), so nothing that
 * depends on it changes before mount.
 */
export function useInView(
  ref: React.RefObject<HTMLElement | null>,
  threshold = 0.5,
): boolean {
  const [inView, setInView] = useState(true);
  useEffect(() => {
    const el = ref.current;
    if (!el || typeof IntersectionObserver === "undefined") return;
    const observer = new IntersectionObserver(
      (entries) => {
        const entry = entries[entries.length - 1];
        if (!entry) return;
        // A carousel taller than the viewport can never be half visible: then covering at
        // least `threshold` of the viewport counts as in view.
        const viewport = entry.rootBounds?.height ?? 0;
        const coversViewport =
          viewport > 0 && (entry.intersectionRect?.height ?? 0) >= viewport * threshold;
        setInView(
          entry.isIntersecting && (entry.intersectionRatio >= threshold || coversViewport),
        );
      },
      // Fine steps: the tall-element rule depends on the visible height, not one ratio crossing.
      { threshold: STEPS },
    );
    observer.observe(el);
    return () => observer.disconnect();
  }, [ref, threshold]);
  return inView;
}

"use client";

import { useCallback, useEffect, useRef, useState } from "react";
import type { MediaItem } from "../types";

type Recovery = (item: MediaItem) => Promise<string | void> | string | void;

/** One entry per item id + host URL: the host changing `url` starts over. */
const basisOf = (item: MediaItem) => `${item.id}\u0000${item.url}`;

export interface MediaRecovery {
  /** The URL to render: the replacement after a successful recovery, else `item.url`. */
  urlFor: (item: MediaItem) => string;
  /** Call from the media element's `error` event. */
  onError: (item: MediaItem) => void;
}

/**
 * `onMediaError` once per item + URL (C8): a resolved string replaces the URL and the element
 * retries; a second failure (of the replacement, or after a void / rejected answer) never asks
 * again. Without a handler it does nothing.
 */
export function useMediaRecovery(onMediaError: Recovery | undefined): MediaRecovery {
  const [replacements, setReplacements] = useState<Record<string, string>>({});
  const askedRef = useRef(new Set<string>());
  const handlerRef = useRef(onMediaError);
  useEffect(() => {
    handlerRef.current = onMediaError;
  });

  const urlFor = useCallback(
    (item: MediaItem) => replacements[basisOf(item)] ?? item.url,
    [replacements],
  );

  const onError = useCallback((item: MediaItem) => {
    const handler = handlerRef.current;
    const basis = basisOf(item);
    if (!handler || askedRef.current.has(basis)) return;
    askedRef.current.add(basis);
    const apply = (next: string | void) => {
      if (typeof next === "string" && next && next !== item.url) {
        setReplacements((prev) => ({ ...prev, [basis]: next }));
      }
    };
    try {
      const result = handler(item);
      if (result && typeof (result as Promise<unknown>).then === "function") {
        (result as Promise<string | void>).then(apply, () => {});
      } else {
        apply(result as string | void);
      }
    } catch {
      // A throwing handler is a failed recovery: keep the broken media, never ask again.
    }
  }, []);

  return { urlFor, onError };
}

import type { CSSProperties } from "react";
import type { MediaCarouselAspect, MediaItem } from "../types";

export const DEFAULT_MIN_RATIO = 4 / 5;
export const DEFAULT_MAX_RATIO = 1.91;

const FIXED_CLASS: Record<Exclude<MediaCarouselAspect, "natural-clamped">, string> = {
  square: "aspect-square",
  video: "aspect-video",
  portrait: "aspect-[3/4]",
  auto: "",
};

/** `w / h` clamped to `[min, max]`; `null` when the size is unknown or invalid. */
export function clampRatio(
  width: number | undefined,
  height: number | undefined,
  min: number,
  max: number,
): number | null {
  if (!width || !height || !Number.isFinite(width / height) || width <= 0 || height <= 0) return null;
  const lo = Math.min(min, max);
  const hi = Math.max(min, max);
  return Math.min(hi, Math.max(lo, width / height));
}

/** The intrinsic size an item declares, if any. */
export function declaredRatio(item: MediaItem | undefined, min: number, max: number): number | null {
  return item ? clampRatio(item.width, item.height, min, max) : null;
}

export interface FrameStyle {
  className: string;
  style?: CSSProperties;
}

/**
 * The slide frame: a fixed aspect class, or for `natural-clamped` an inline `aspect-ratio`
 * (`ratio` = the clamped natural ratio; square until it is known).
 */
export function frameFor(aspect: MediaCarouselAspect, ratio: number | null): FrameStyle {
  if (aspect !== "natural-clamped") return { className: FIXED_CLASS[aspect] };
  if (ratio === null) return { className: "aspect-square" };
  return { className: "", style: { aspectRatio: String(ratio) } };
}

import {
  defaultMediaCarouselLabels,
  type MediaCarouselLabels,
  type ResolvedMediaCarouselLabels,
} from "../types";

/**
 * Merge `labels` over the defaults (an `undefined` value never erases a default, C2) and turn
 * the deprecated 0.2 string forms of `goToSlide` / `slideAriaLabel` into functions.
 */
export function resolveLabels(labels: MediaCarouselLabels | undefined): ResolvedMediaCarouselLabels {
  const out: ResolvedMediaCarouselLabels = { ...defaultMediaCarouselLabels };
  if (!labels) return out;
  if (labels.carouselLabel !== undefined) out.carouselLabel = labels.carouselLabel;
  if (labels.previousSlide !== undefined) out.previousSlide = labels.previousSlide;
  if (labels.nextSlide !== undefined) out.nextSlide = labels.nextSlide;
  if (labels.counter !== undefined) out.counter = labels.counter;
  if (labels.carouselRoleDescription !== undefined) {
    out.carouselRoleDescription = labels.carouselRoleDescription;
  }
  if (labels.slideRoleDescription !== undefined) out.slideRoleDescription = labels.slideRoleDescription;

  const goTo = labels.goToSlide;
  if (typeof goTo === "function") out.goToSlide = goTo;
  else if (typeof goTo === "string") out.goToSlide = (position) => `${goTo} ${position}`;

  const slide = labels.slideAriaLabel;
  if (typeof slide === "function") out.slideAriaLabel = slide;
  else if (typeof slide === "string") {
    out.slideAriaLabel = (position, total) =>
      // template-ok: deprecated 0.2 string form of slideAriaLabel, kept as an alias
      slide.replace("{index}", String(position)).replace("{total}", String(total));
  }
  return out;
}

/**
 * A valid BCP 47 tag for `locale`, else `"en"`. An invalid tag (`"en_US"` from an i18n library)
 * makes `Intl` throw — that must not take down the render.
 */
export function resolveLocale(locale: string | undefined): string {
  if (!locale) return "en";
  try {
    return Intl.getCanonicalLocales(locale)[0] ?? "en";
  } catch {
    return "en";
  }
}
